      "mediaId": null,
      "visualObservation": null
    },
    {
      "location": "PASSAGE",
      "quote": "가령 점도가 커서 오네소르게 수가 이 범위보다 크게 되면 잉크가 노즐 밖으로 나오지 못한다.",
      "mediaId": null,
      "visualObservation": null
    }
  ],
  "errors": [],
  "errorHypothesis": null,
  "selectionMismatchQuestion": null,
